// Instalaciones de ejemplo. Más adelante saldrán del panel de la web.
// "averia" solo sirve para simular: el vigilante NO la mira, la tiene que adivinar.
return [
  { nombre: 'Finca El Olivar',     pueblo: 'Martos',    lat: 37.72, lon: -3.97, kWp: 4.5, averia: 'ninguna' },
  { nombre: 'Cortijo Los Pinos',   pueblo: 'Cazorla',   lat: 37.91, lon: -3.00, kWp: 6,   averia: 'suciedad' },
  { nombre: 'Invernadero La Vega', pueblo: 'Níjar',     lat: 36.97, lon: -2.21, kWp: 9,   averia: 'fila' },
  { nombre: 'Pozo San José',       pueblo: 'Zafarraya', lat: 36.98, lon: -4.14, kWp: 7.5, averia: 'inversor' },
].map(i => ({ json: i }));

const instalaciones = $('Instalaciones').all();
const tiempos = $input.all();
const RENDIMIENTO = 0.8;
const PRECIO_KWH = 0.15;   // € que le cuesta al cliente cada kWh que no producen sus placas

// ---------- SIMULADOR (en real, este historial lo da la API del inversor) ----------
function factorSimulado(averia, k, total) {
  if (averia === 'suciedad') return 1 - 0.25 * k / (total - 1);   // baja poco a poco hasta el 75 %
  if (averia === 'fila')     return k >= total - 4 ? 0.5 : 1;     // cae de golpe hace 4 días
  if (averia === 'inversor') return k >= total - 2 ? 0 : 1;       // parado desde anteayer
  return 1;
}

// ---------- utilidades ----------
const media = a => a.reduce((s, x) => s + x, 0) / a.length;
const pct = x => Math.round(x * 100) + ' %';
const fecha = s => new Date(s + 'T12:00:00').toLocaleDateString('es-ES', { day: 'numeric', month: 'short' });

return instalaciones.map((inst, i) => {
  const { nombre, pueblo, kWp, averia } = inst.json;
  const d = tiempos[i].json.daily;

  // 1. HISTORIAL de los últimos 14 días (quitamos hoy, que aún no ha terminado)
  const dias = d.time.slice(0, -1);
  const historial = dias.map((dia, k) => {
    const sol = d.shortwave_radiation_sum[k] / 3.6;
    const esperado = kWp * sol * RENDIMIENTO;
    const real = esperado * factorSimulado(averia, k, dias.length) * (0.95 + Math.random() * 0.06);
    return { dia, sol, esperado, real, rinde: real / esperado };
  });

  // 2. Solo se juzgan los días con sol suficiente
  const validos = historial.filter(h => h.sol >= 1.5);
  const base = { nombre, pueblo };
  if (validos.length < 5) {
    return { json: { ...base, estado: '⚪', diagnostico: 'Pocos días de sol para juzgar', detalle: '' } };
  }

  const ayer = validos.at(-1);
  const reciente = media(validos.slice(-3).map(h => h.rinde));   // últimos 3 días
  const antes = media(validos.slice(0, 5).map(h => h.rinde));    // primeros 5 días
  const perdidos = historial.reduce((s, h) => s + Math.max(0, h.esperado - h.real), 0);
  const coste = `Perdidos en 2 semanas: ${perdidos.toFixed(0)} kWh (≈ ${(perdidos * PRECIO_KWH).toFixed(0)} €)`;

  // ¿Hubo una caída de golpe? Buscamos el mayor bajón de un día para otro
  let salto = { caida: 0 };
  for (let k = 1; k < validos.length; k++) {
    const caida = validos[k - 1].rinde - validos[k].rinde;
    if (caida > salto.caida) salto = { caida, dia: validos[k].dia, de: validos[k - 1].rinde, a: validos[k].rinde };
  }

  // ¿Cuántos días seguidos lleva sin producir, contando desde ayer hacia atrás?
  const parados = [];
  for (let k = validos.length - 1; k >= 0 && validos[k].rinde < 0.05; k--) parados.unshift(validos[k]);

  // 3. EL DIAGNÓSTICO, mirando la historia y no solo ayer
  let estado, diagnostico, detalle;
  if (reciente >= 0.85 && ayer.rinde >= 0.85) {
    estado = '🟢'; diagnostico = 'Produce lo que debe'; detalle = '';
  } else if (parados.length >= 2) {
    estado = '🔴'; diagnostico = 'Inversor parado o sin conexión';
    detalle = `Sin producción desde el ${fecha(parados[0].dia)}. ${coste}`;
  } else if (parados.length === 1) {
    estado = '🟡'; diagnostico = 'Ayer no produjo: puede ser un corte puntual';
    detalle = 'Si mañana sigue igual, se avisará como avería';
  } else if (salto.caida >= 0.3) {
    estado = '🔴'; diagnostico = 'Caída de golpe: posible fila de paneles caída';
    detalle = `El ${fecha(salto.dia)} pasó del ${pct(salto.de)} al ${pct(salto.a)}. ${coste}`;
  } else if (antes - reciente >= 0.1) {
    estado = '🟡'; diagnostico = 'Baja poco a poco: suciedad, toca limpieza';
    detalle = `Del ${pct(antes)} al ${pct(reciente)} en 2 semanas. ${coste}`;
  } else {
    estado = '🟡'; diagnostico = 'Produce algo menos de lo normal';
    detalle = `Rinde un ${pct(reciente)} de lo esperado. ${coste}`;
  }

  return { json: { ...base, estado, diagnostico, detalle } };
});

const filas = $input.all().map(i => i.json);

const orden = { '🔴': 0, '🟡': 1, '⚪': 2, '🟢': 3 };
filas.sort((a, b) => orden[a.estado] - orden[b.estado]);

const problemas = filas.filter(f => f.estado === '🔴' || f.estado === '🟡');
const ayer = $('Tiempo de ayer').first().json.daily.time.at(-2);

let texto = `<b>☀️ Vigilante de instalaciones · ${ayer}</b>\n`;
texto += problemas.length
  ? `⚠️ ${problemas.length} de ${filas.length} instalaciones necesitan atención\n\n`
  : `✅ Las ${filas.length} instalaciones funcionan bien\n\n`;

for (const f of filas) {
  texto += `${f.estado} <b>${f.nombre}</b> (${f.pueblo})\n`;
  if (f.estado !== '🟢') texto += `     ${f.diagnostico}\n`;
  if (f.detalle) texto += `     <i>${f.detalle}</i>\n`;
}

return [{ json: { texto } }];
